class Solution {
public:
    vector<int> queryResults(int limit, vector<vector<int>>& queries) {
        unordered_map<int,int> ballColor;
        unordered_map<int,int> colorCount;
        vector<int> result;
        result.reserve(queries.size());
        int distinct = 0;
        for (auto& q : queries) {
            int x = q[0], y = q[1];
            auto it = ballColor.find(x);
            if (it != ballColor.end()) {
                int oldColor = it->second;
                if (oldColor == y) {
                    result.push_back(distinct);
                    continue;
                }
                if (--colorCount[oldColor] == 0) {
                    colorCount.erase(oldColor);
                    distinct--;
                }
            }
            ballColor[x] = y;
            if (colorCount[y]++ == 0) {
                distinct++;
            }
            result.push_back(distinct);
        }
        return result;
    }
};
